public sealed class GlobalExceptionHandler(
    IProblemDetailsService problemDetails,
    IHostEnvironment env,
    ILogger<GlobalExceptionHandler> logger) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(
        HttpContext context, Exception exception, CancellationToken cancellationToken)
    {
        var correlationId = context.Request.Headers["X-Correlation-ID"].FirstOrDefault()
            ?? context.TraceIdentifier;

        logger.LogError(exception, "Unhandled {CorrelationId} {Path}", correlationId, context.Request.Path);

        var (status, title, detail) = exception switch
        {
            NotFoundException nf => (404, "Resource not found", nf.Message),
            ValidationException ve => (400, "Validation failed", ve.Message),
            _ => (500, "An unexpected error occurred.", env.IsDevelopment() ? exception.Message : null)
        };

        context.Response.StatusCode = status;
        return await problemDetails.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = context,
            Exception = exception,
            ProblemDetails =
            {
                Title = title,
                Detail = detail,
                Status = status,
                Extensions = { ["correlationId"] = correlationId }
            }
        });
    }
}

