public sealed class ValidationExceptionHandler : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(HttpContext ctx, Exception ex, CancellationToken ct)
    {
        if (ex is not FluentValidation.ValidationException fve) return false;

        ctx.Response.StatusCode = 400;
        var errors = fve.Errors.GroupBy(e => e.PropertyName)
            .ToDictionary(g => g.Key, g => g.Select(e => e.ErrorMessage).ToArray());
        await ctx.Response.WriteAsJsonAsync(new ValidationProblemDetails(errors));
        return true;
    }
}

builder.Services.AddExceptionHandler<ValidationExceptionHandler>();
builder.Services.AddExceptionHandler<GlobalExceptionHandler>(); // fallback

[Fact]
public async Task Unhandled_exception_returns_problem_details_with_correlation_id()
{
    await using var factory = new WebApplicationFactory<Program>();
    var client = factory.CreateClient();
    client.DefaultRequestHeaders.Add("X-Correlation-ID", "test-corr-123");

    var response = await client.GetAsync("/throw");
    var body = await response.Content.ReadFromJsonAsync<JsonElement>();

    Assert.Equal(HttpStatusCode.InternalServerError, response.StatusCode);
    Assert.Equal("application/problem+json", response.Content.Headers.ContentType?.MediaType);
    Assert.Equal("test-corr-123", body.GetProperty("correlationId").GetString());
}
